-- Reparacion puntual de textos del catalogo de prueba de VetStock.
-- Solo cambia valores que coinciden EXACTAMENTE con una doble codificacion
-- de los nombres/direcciones/descripciones del esquema inicial.
-- Conserva usuarios, passwords, IDs, responsables, pedidos y firmas.
-- Guarda los valores anteriores en respaldo_textos_utf8 antes de cambiarlos.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS respaldo_textos_utf8 (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    tabla VARCHAR(30) NOT NULL,
    columna VARCHAR(30) NOT NULL,
    registro_id BIGINT NOT NULL,
    anterior LONGTEXT CHARACTER SET utf8mb4 NOT NULL,
    corregido LONGTEXT CHARACTER SET utf8mb4 NOT NULL,
    fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TEMPORARY TABLE mapa_textos_utf8 (
    tabla VARCHAR(30), columna VARCHAR(30),
    anterior LONGTEXT CHARACTER SET utf8mb4,
    corregido LONGTEXT CHARACTER SET utf8mb4
) ENGINE=InnoDB;


START TRANSACTION;
SET @fecha_reparacion = NOW();

SELECT 'clinicas','nombre',t.id,t.nombre,m.corregido,@fecha_reparacion
FROM clinicas t JOIN mapa_textos_utf8 m ON m.tabla='clinicas' AND m.columna='nombre' AND HEX(t.nombre)=HEX(m.anterior);
UPDATE clinicas t JOIN mapa_textos_utf8 m ON m.tabla='clinicas' AND m.columna='nombre' AND HEX(t.nombre)=HEX(m.anterior)
SET t.nombre=m.corregido;

SELECT 'clinicas','direccion',t.id,t.direccion,m.corregido,@fecha_reparacion
FROM clinicas t JOIN mapa_textos_utf8 m ON m.tabla='clinicas' AND m.columna='direccion' AND HEX(t.direccion)=HEX(m.anterior);
UPDATE clinicas t JOIN mapa_textos_utf8 m ON m.tabla='clinicas' AND m.columna='direccion' AND HEX(t.direccion)=HEX(m.anterior)
SET t.direccion=m.corregido;

SELECT 'usuarios','nombre_completo',t.id,t.nombre_completo,m.corregido,@fecha_reparacion
FROM usuarios t JOIN mapa_textos_utf8 m ON m.tabla='usuarios' AND m.columna='nombre_completo' AND HEX(t.nombre_completo)=HEX(m.anterior);
UPDATE usuarios t JOIN mapa_textos_utf8 m ON m.tabla='usuarios' AND m.columna='nombre_completo' AND HEX(t.nombre_completo)=HEX(m.anterior)
SET t.nombre_completo=m.corregido;

SELECT 'productos','nombre',t.id,t.nombre,m.corregido,@fecha_reparacion
FROM productos t JOIN mapa_textos_utf8 m ON m.tabla='productos' AND m.columna='nombre' AND HEX(t.nombre)=HEX(m.anterior);
UPDATE productos t JOIN mapa_textos_utf8 m ON m.tabla='productos' AND m.columna='nombre' AND HEX(t.nombre)=HEX(m.anterior)
SET t.nombre=m.corregido;

SELECT 'productos','descripcion',t.id,t.descripcion,m.corregido,@fecha_reparacion
FROM productos t JOIN mapa_textos_utf8 m ON m.tabla='productos' AND m.columna='descripcion' AND HEX(t.descripcion)=HEX(m.anterior);
UPDATE productos t JOIN mapa_textos_utf8 m ON m.tabla='productos' AND m.columna='descripcion' AND HEX(t.descripcion)=HEX(m.anterior)
SET t.descripcion=m.corregido;

COMMIT;

SELECT tabla,columna,COUNT(*) AS campos_corregidos
FROM respaldo_textos_utf8 WHERE fecha=@fecha_reparacion GROUP BY tabla,columna;

SELECT id,nombre,direccion FROM clinicas ORDER BY id;
SELECT id,username,nombre_completo FROM usuarios ORDER BY id;
DROP TEMPORARY TABLE mapa_textos_utf8;
